#pragma once
#include <cstring>
#include <iostream>

class Memory {
public:
    static constexpr unsigned int MEMORY_SIZE = 1024 * 1024; // Example size, adjust as needed
    unsigned char mem[MEMORY_SIZE];
    unsigned char placeholder;

    Memory() : placeholder(0) {
        std::memset(mem, 0, sizeof(mem));
    }

    bool check_addr(unsigned int addr) {
        // assert(addr < MEMORY_SIZE); // Debugging aid (commented out)
        return addr < MEMORY_SIZE;
    }

    Immediate read_word(unsigned int addr) {
        if (!check_addr(addr + 3)) {
            return 0;
        }
        Immediate result = 0;
        for (unsigned int i = 0; i < 4; ++i) {
            result |= static_cast<Immediate>(mem[addr + i]) << (8 * i);
        }
        return result;
    }

    void write_word(unsigned int addr, Immediate imm) {
        if (!check_addr(addr + 3)) {
            return;
        }
        for (unsigned int i = 0; i < 4; ++i) {
            mem[addr + i] = static_cast<unsigned char>((imm >> (8 * i)) & 0xFF);
        }
    }

    unsigned short read_ushort(unsigned int addr) {
        if (!check_addr(addr + 1)) {
            return 0;
        }
        return static_cast<unsigned short>(mem[addr]) | (static_cast<unsigned short>(mem[addr + 1]) << 8);
    }

    void write_ushort(unsigned int addr, unsigned short imm) {
        if (!check_addr(addr + 1)) {
            return;
        }
        mem[addr] = static_cast<unsigned char>(imm & 0xFF);
        mem[addr + 1] = static_cast<unsigned char>((imm >> 8) & 0xFF);
    }

    unsigned char &operator[](unsigned int addr) {
        return check_addr(addr) ? mem[addr] : placeholder;
    }

    void debug() {
        const unsigned int start = 0x20000 - 0x10;
        const unsigned int end = 0x20000;
        for (unsigned int addr = start; addr <= end; ++addr) {
            std::cout << std::hex << static_cast<int>(mem[addr]) << " ";
        }
        std::cout << std::endl;
    }
};
